int main() {
 for (const auto& c:cases) {
  double levels[2]{};
  for (int gesture=0;gesture<2;++gesture) {
   cs80::ParamValues p;for(int i=0;i<cs80::P_numParams;++i)p[i]=c.values[(size_t)i];p[cs80::P_volume]=.5f;
   auto engine=std::make_unique<cs80::Engine>();engine->prepare(48000);engine->setParams(p);
   engine->noteOn(c.note,gesture==0?.25f:.85f,1);engine->channelPressure(1,0);
   std::array<float,256> block{};double sum=0,peak=0;int count=0;
   for(int at=0;at<216000;at+=128) {
    const int frames=std::min(128,216000-at);engine->render(block.data(),frames);
    for(int i=0;i<2*frames;++i) {
     if(!std::isfinite(block[(size_t)i])||std::abs(block[(size_t)i])>1.f)return 2;
     peak=std::max(peak,std::abs((double)block[(size_t)i]));
     if(at+i/2>=192000){sum+=(double)block[(size_t)i]*block[(size_t)i];++count;}
    }
   }
   levels[gesture]=20*std::log10(std::sqrt(sum/count));
  }
  std::printf("%s,%s,%.9f,%.9f,%.9f\n",c.name,c.version,levels[0],levels[1],levels[1]-levels[0]);
 }
}
